// NothingFound, ReplaceCandidates). Do not edit by hand: change the spec and propagate.
import { describe, expect, it } from "vitest";
import {
  defaultIdeaConfig,
  type IdeaConfig,
  type RecipeIdea,
  type RecipeIdeaId,
  type ResearchRequest,
} from "@weekly-planner/domain";
import type {
  IdeaResearcher,
  InspirationReader,
  RecipeIdeaRepository,
  ResearchRequestLog,
} from "../src/ports/recipe-ideas.js";
import { DeleteIdea, NoteIdea, ResearchIdea } from "../src/use-cases/recipe-ideas.js";
import { AC, FakeClock, ME, SequenceIds } from "./support/in-memory.js";

const HOUR = 3_600_000;

type ResearchQuery = Parameters<IdeaResearcher["research"]>[0];

class InMemoryIdeas implements RecipeIdeaRepository {
  readonly byId = new Map<RecipeIdeaId, RecipeIdea>();
  saves = 0;
  async get(id: RecipeIdeaId) {
    return this.byId.get(id) ?? null;
  }
  async save(idea: RecipeIdea) {
    this.saves++;
    this.byId.set(idea.id, idea);
  }
  async remove(id: RecipeIdeaId) {
    this.byId.delete(id);
  }
  async listAll() {
    return [...this.byId.values()];
  }
}

class InMemoryResearchRequests implements ResearchRequestLog {
  readonly all: ResearchRequest[] = [];
  async add(request: ResearchRequest) {
    this.all.push(request);
  }
  async listSince(from: number) {
    return this.all.filter((r) => r.requestedAt >= from);
  }
}

/** The inspiration link read under the safe-fetch rules: null stands for a link that could not be read. */
class FakeInspiration implements InspirationReader {
  readonly read: string[] = [];
  answer: (address: string) => Promise<string | null> = async () => "Ofenkürbis mit Salbei und Feta";
  async readInspiration(address: string) {
    this.read.push(address);
    return this.answer(address);
  }
}

const useful = {
  candidates: [{ title: "Kürbisgnocchi", link: "https://example.org/gnocchi", summary: "Mit Salbei" }],
};

class FakeResearcher implements IdeaResearcher {
  readonly asked: ResearchQuery[] = [];
  answer: (query: ResearchQuery) => Promise<unknown> = async () => useful;
  async research(query: ResearchQuery) {
    this.asked.push(query);
    return this.answer(query);
  }
}

/** Moves the fake clock forward by whole hours (it counts in hours of a day). */
const advance = (clock: FakeClock, ms: number) => {
  const target = clock.now() + ms;
  const d = new Date(target);
  clock.date = d.toISOString().slice(0, 10) as FakeClock["date"];
  clock.hour = d.getUTCHours();
  expect(clock.now()).toBe(target);
};

function harness(config: IdeaConfig = defaultIdeaConfig) {
  const repo = new InMemoryIdeas();
  const requests = new InMemoryResearchRequests();
  const researcher = new FakeResearcher();
  const inspiration = new FakeInspiration();
  const clock = new FakeClock();
  return {
    repo,
    requests,
    researcher,
    inspiration,
    clock,
    note: new NoteIdea({ ideas: repo, clock, ids: new SequenceIds() }),
    remove: new DeleteIdea({ ideas: repo }),
    research: new ResearchIdea({ ideas: repo, requests, researcher, inspiration, clock }, config),
  };
}

async function noted(h: ReturnType<typeof harness>, cmd: { note?: string; inspirationLink?: string } = {}) {
  const r = await h.note.execute({ member: ME, title: "etwas mit Kürbis", ...cmd });
  if (!r.ok) throw new Error(r.reason);
  return r.value;
}

/** Answers with nothing usable: a failure, malformed shapes, an empty list, and candidates that all fail the checks. */
const nothingUsable: [string, () => Promise<unknown>][] = [
  [
    "the model fails",
    async () => {
      throw new Error("503");
    },
  ],
  ["the answer is not an object", async () => "Leider nichts gefunden."],
  ["the answer has no candidate list", async () => ({ recipes: useful.candidates })],
  ["the candidate list is empty", async () => ({ candidates: [] })],
  [
    "no candidate survives the checks",
    async () => ({
      candidates: [
        { title: "x", link: "ftp://example.org/x", summary: "" },
        { title: "  ", link: "https://example.org/y", summary: "" },
        { title: "<a href='https://e.org'></a>", link: "https://example.org/z", summary: "" },
      ],
    }),
  ],
];

describe("ResearchIdea: the inspiration link", () => {
  it("reads the idea's inspiration link and hands its text to the model beside title and note", async () => {
    const h = harness();
    const idea = await noted(h, { note: "Hokkaido", inspirationLink: "https://example.org/inspo" });
    expect((await h.research.execute({ member: ME, idea: idea.id })).ok).toBe(true);
    expect(h.inspiration.read).toEqual(["https://example.org/inspo"]);
    expect(h.researcher.asked).toEqual([
      { title: "etwas mit Kürbis", note: "Hokkaido", inspiration: "Ofenkürbis mit Salbei und Feta" },
    ]);
  });

  it("reads nothing for an idea without an inspiration link, and the model gets no inspiration", async () => {
    const h = harness();
    const idea = await noted(h, { note: "Hokkaido" });
    expect((await h.research.execute({ member: ME, idea: idea.id })).ok).toBe(true);
    expect(h.inspiration.read).toEqual([]);
    expect(h.researcher.asked).toEqual([{ title: "etwas mit Kürbis", note: "Hokkaido", inspiration: null }]);
  });

  it("reads the link the idea has when the member asks, after an edit too", async () => {
    const h = harness();
    const idea = await noted(h, { inspirationLink: "https://example.org/old" });
    await h.repo.save({ ...idea, inspirationLink: "https://example.org/new" });
    expect((await h.research.execute({ member: ME, idea: idea.id })).ok).toBe(true);
    expect(h.inspiration.read).toEqual(["https://example.org/new"]);
  });

  it("does not fail the research when the link cannot be read: it goes on with title and note only", async () => {
    const h = harness();
    const idea = await noted(h, { note: "Hokkaido", inspirationLink: "http://127.0.0.1/admin" });
    h.inspiration.answer = async () => null;
    const r = await h.research.execute({ member: ME, idea: idea.id });
    expect(r.ok && r.value.candidates.map((c) => c.title)).toEqual(["Kürbisgnocchi"]);
    expect(h.researcher.asked).toEqual([{ title: "etwas mit Kürbis", note: "Hokkaido", inspiration: null }]);
    expect(h.requests.all).toHaveLength(1);
  });

  it("does not fail the research when reading the link throws: it goes on with title and note only", async () => {
    const h = harness();
    const idea = await noted(h, { inspirationLink: "https://example.org/broken" });
    h.inspiration.answer = async () => {
      throw new Error("socket hang up");
    };
    expect((await h.research.execute({ member: ME, idea: idea.id })).ok).toBe(true);
    expect(h.researcher.asked).toEqual([{ title: "etwas mit Kürbis", note: null, inspiration: null }]);
  });

  it("reads no link for a member over the limit", async () => {
    const h = harness({ ...defaultIdeaConfig, maxResearchPerHour: 1 });
    const idea = await noted(h, { inspirationLink: "https://example.org/inspo" });
    expect((await h.research.execute({ member: ME, idea: idea.id })).ok).toBe(true);
    expect(await h.research.execute({ member: ME, idea: idea.id })).toEqual({ ok: false, reason: "rate_limited" });
    expect(h.inspiration.read).toHaveLength(1);
    expect(h.researcher.asked).toHaveLength(1);
  });
});

describe("CountUsefulResearch", () => {
  it("records a research that brought candidates, when its answer arrives", async () => {
    const h = harness();
    const idea = await noted(h);
    const asked = h.clock.now();
    h.researcher.answer = async () => {
      advance(h.clock, HOUR);
      return useful;
    };
    expect((await h.research.execute({ member: AC, idea: idea.id })).ok).toBe(true);
    expect(h.requests.all).toEqual([{ requestedBy: AC, requestedAt: asked + HOUR }]);
  });

  for (const [name, answer] of nothingUsable) {
    it(`records nothing when ${name}`, async () => {
      const h = harness();
      const idea = await noted(h);
      h.researcher.answer = answer;
      await h.research.execute({ member: ME, idea: idea.id });
      expect(h.requests.all).toEqual([]);
    });
  }

  it("counts a useful research even when the idea was deleted while the model worked", async () => {
    const h = harness();
    const idea = await noted(h);
    h.researcher.answer = async () => {
      await h.remove.execute({ member: AC, idea: idea.id });
      return useful;
    };
    await h.research.execute({ member: ME, idea: idea.id });
    expect(await h.repo.get(idea.id)).toBeNull();
    expect(h.requests.all).toEqual([{ requestedBy: ME, requestedAt: h.clock.now() }]);
  });

  it("records nothing for a research that found nothing on an idea deleted meanwhile", async () => {
    const h = harness();
    const idea = await noted(h);
    h.researcher.answer = async () => {
      await h.remove.execute({ member: AC, idea: idea.id });
      return { candidates: [] };
    };
    expect((await h.research.execute({ member: ME, idea: idea.id })).ok).toBe(false);
    expect(h.requests.all).toEqual([]);
  });
});

describe("ResearchIdea: the hourly limit counts useful researches only", () => {
  it("lets a member go on asking after any number of researches that found nothing", async () => {
    const h = harness({ ...defaultIdeaConfig, maxResearchPerHour: 2 });
    const idea = await noted(h);
    for (const [, answer] of nothingUsable) {
      h.researcher.answer = answer;
      expect(await h.research.execute({ member: ME, idea: idea.id })).toEqual({ ok: false, reason: "nothing_found" });
    }
    h.researcher.answer = async () => useful;
    expect((await h.research.execute({ member: ME, idea: idea.id })).ok).toBe(true);
    expect((await h.research.execute({ member: ME, idea: idea.id })).ok).toBe(true);
    const asked = h.researcher.asked.length;
    expect(await h.research.execute({ member: ME, idea: idea.id })).toEqual({ ok: false, reason: "rate_limited" });
    expect(h.researcher.asked).toHaveLength(asked);
    // The other member has a limit of their own.
    expect((await h.research.execute({ member: AC, idea: idea.id })).ok).toBe(true);
  });

  it("frees a useful research from the count exactly an hour after its answer arrived", async () => {
    const h = harness({ ...defaultIdeaConfig, maxResearchPerHour: 1 });
    const idea = await noted(h);
    h.researcher.answer = async () => {
      advance(h.clock, HOUR);
      return useful;
    };
    expect((await h.research.execute({ member: ME, idea: idea.id })).ok).toBe(true);
    h.researcher.answer = async () => useful;
    // Asked an hour after the first ask, but only now has its answer arrived: still within the hour.
    expect(await h.research.execute({ member: ME, idea: idea.id })).toEqual({ ok: false, reason: "rate_limited" });
    advance(h.clock, HOUR);
    expect((await h.research.execute({ member: ME, idea: idea.id })).ok).toBe(true);
  });
});

describe("NothingFound", () => {
  for (const [name, answer] of nothingUsable) {
    it(`tells the member nothing was found and keeps the old candidates and clock when ${name}`, async () => {
      const h = harness();
      const idea = await noted(h);
      const first = await h.research.execute({ member: ME, idea: idea.id });
      if (!first.ok) throw new Error(first.reason);
      advance(h.clock, 2 * HOUR);
      const savesBefore = h.repo.saves;
      h.researcher.answer = answer;
      expect(await h.research.execute({ member: ME, idea: idea.id })).toEqual({ ok: false, reason: "nothing_found" });
      expect(await h.repo.get(idea.id)).toEqual(first.value);
      expect((await h.repo.get(idea.id))?.lastTouchedAt).toBe(first.value.lastTouchedAt);
      expect(h.repo.saves).toBe(savesBefore);
      // The member may ask again at once.
      h.researcher.answer = async () => useful;
      expect((await h.research.execute({ member: ME, idea: idea.id })).ok).toBe(true);
    });
  }

  it("keeps an idea that never had candidates without any", async () => {
    const h = harness();
    const idea = await noted(h);
    advance(h.clock, HOUR);
    h.researcher.answer = async () => ({ candidates: [] });
    expect(await h.research.execute({ member: ME, idea: idea.id })).toEqual({ ok: false, reason: "nothing_found" });
    expect(await h.repo.get(idea.id)).toEqual(idea);
  });
});
